assert len(LESSONS) == 48

# 将每课原来的概括性例子补成“输入/设定 → 操作 → 可观察结果”。
# 这些是教学用小例子，数字只用于解释机制，不冒充真实训练记录。
EXAMPLE_DETAILS = [
    "例如输入一封邮件，分类器输出“垃圾邮件”的概率；输入“今天我想”，生成模型则逐个给出后续 token。前者核对类别，后者核对续写。",
    "假设训练文本是“今天晴”，模型读到“今天”后先猜“雨”。把预测与真实的“晴”比较，再调权重；下一轮若“晴”的概率提高，就看到学习效果。",
    "先固定数据、配置和种子，运行两次并记录输出；再只改种子。若两次结果不同，就能区分随机初始化的影响与代码变更的影响。",
    "设输入 x=2、目标 y=4。w=1 时预测 2，平方误差为 4；w=2 时预测 4，误差为 0。改变权重如何影响损失因此可以算出来。",
    "假设把同一篇教程切成 A、B 两段，A 用来训练、B 用来测试。模型可能凭前半篇的措辞猜出后半篇；改为按整篇文档分组后，再看测试分数是否下降。",
    "若正确 token 的概率从 0.1 提高到 0.8，负对数损失会由约 2.30 降到 0.22。这里衡量的是目标 token 概率，而不是回答是否有礼貌。",
    "给两层小网络输入一个数，先算每层输出和最终损失，再把梯度从后一层传回前一层。修改第一层权重后重新前向，观察预测是否跟着变化。",
    "把学习率设得很大时，更新可能一次跨过最低点；设得过小时，许多步仍几乎不动。每次同时画训练和验证损失，才能看出快与稳是否兼得。",
    "把“机器学习”交给两个假设的切分器：一个切为四个单字，另一个切为“机器/学习”。再映射成 ID，就得到长度 4 与长度 2 的序列；切分方案会影响训练长度。",
    "先给“猫”“追”“狗”各取一个 ID，再查表得到向量。若交换“猫”“狗”的位置，ID 集合没变，但位置顺序改变；模型应据此区分谁追谁。",
    "若只看到上一个 token“的”，bigram 很难判断后面是“天气”还是“首都”；若能读到更早的“北京是中国”，选择“首都”就有更多依据。",
    "输入“今天 下雨 所以 带伞”时，“带伞”的位置可关注“下雨”。训练时在“下雨”位置加上因果掩码，验证它看不到尚未出现的“带伞”。",
    "让同一句话经过一个块：注意力先汇入相关前文，FFN 再逐位置变换特征，残差保留原信息。比较块前后的向量，观察每个位置的表示是否更新。",
    "给模型前缀“今天”，它可能给“晴”“下雨”等候选不同分数。训练时拿真实下一个 token 算损失；生成时选一个候选追加，再用更长前缀继续预测。",
    "对同一段提示固定随机种子，分别用较低和较高温度生成。前者通常更集中，后者候选更分散；同时观察是否有重复与跑题，而不只看哪句更有趣。",
    "假设数据池有网页问答、小说和技术文档三类。先给每类记来源、许可与哈希，再抽样查看比例；若小说占九成，模型的续写风格可能被其主导。",
    "取 100 篇文档，先移除空白和乱码，再对完全相同的文本算哈希；对改了标题的转载文章做近重复比较。记录每一步保留多少篇，便于定位误删。",
    "用中文、英文、数字混合句各取十条，编码后再解码，检查是否还原。随后统计每类每百字需要多少 token；如果中文数字被切得异常碎，就回头查词表样本。",
    "按 batch=2、梯度累积=8、长度=1024 计算，一次更新最多处理 16,384 个位置。若计划处理 2B 个位置，先估算更新步数，再扣除填充与不计损失的位置。",
    "先从随机权重开始处理一个小批，计算损失并反向传播；连续累积 8 个小批后才调用一次 optimizer.step()。打印更新前后的权重，确认 step 确实改变参数。",
    "在第 100 步保存完整状态，第 101 步前模拟中断。重新启动时核对恢复的 step、优化器和数据位置，观察下一批是否与预期一致，而不只看文件能否打开。",
    "每隔固定步数记录训练损失、验证损失、tokens/s 与显存。若训练损失下降、验证损失却持续上升，就定位最近的数据或参数变化，再决定是否暂停。",
    "准备十条从未参与训练的固定提示，对两个检查点使用同样的温度与最大输出长度。除损失外，逐条标注重复、乱码、语言切换和续写偏差。",
    "输入“你好”后若模型接着写“用户：”或新增人物名，说明它可能把输入当剧本续写。改用明确角色模板做 SFT 后，再用同一提示核对是否变成直接回答。",
    "构造“用户：你好／助手：你好！”的样本，把用户部分标签设为不计损失，仅在“你好！”位置优化。打印掩码，确认模型没有被训练去生成用户自己的话。",
    "用同一批封存提示比较 SFT 前后：记录“你好”的自然度，也测知识问答和约束题。若一项上升、一项下降，就保留两边原文而非只报平均分。",
    "封存集先写好“回答不超过 20 字”“记住用户喜欢茶”等题。训练后一次性运行新旧模型，逐题记录成功、失败与生成参数，避免训练后临时改题。",
    "同一问题准备两条回答：优选回答满足字数限制，劣选回答虽然流畅却超字数。DPO 比较两者相对概率；随后仍用未见过的限制题验证是否泛化。",
    "设一个玩具环境给合规回答奖励 1、违规回答奖励 0。策略每轮生成候选并据奖励调整；若它学会只输出空话来拿分，说明奖励设计出了偏差。",
    "列出四轮对话：第一轮给偏好，第二轮改约束，第三轮追问原因，第四轮检查记忆。逐轮标记角色、结束、约束和事实性，任何一项回退都单独报告。",
    "将模型权重、结构配置、tokenizer 和结束 token 放进同一推理目录。若故意换成不匹配的 tokenizer，观察输出异常；再恢复配套文件核对。",
    "向本地接口发送包含 prompt 与 max_tokens 的 JSON，请求成功时返回文本与状态码。再分别发送空提示、过长提示，核对错误码与超时行为是否稳定。",
    "让模型生成三个片段，服务端依次发出三条 SSE data 事件，最后发完成事件。客户端边收边显示；中途断开时检查是否能正确结束而不是无限等待。",
    "用户问天气时，模型先给出工具名和城市参数，程序核验城市后才调用天气源。若参数缺失，程序返回结构化错误，模型再根据错误向用户澄清。",
    "前端字段叫 messages，后端只接受 prompt；适配器把多轮消息序列化，并把后端生成结果改回前端格式。测试还要覆盖结束标记和错误码。",
    "给同一服务配置本机访问与受控远程访问两种入口，记录鉴权失败、限流和超时响应。对比后确认训练状态页面与模型推理接口没有共用不必要的权限。",
    "从客户端发“你好”，依次记录网关、推理服务和模型的版本及耗时；再模拟模型尚未加载。正常与异常两条链都能复现，才算联调完成。",
    "读本案例配置中的 vocab_size=32768 和 block_size=1024，分别写下“可用 ID 种类”和“单次序列长度”。再对照模型参数统计，避免把三个数字都叫规模。",
    "从原始语料抽出一份样本，记录来源与过滤原因；用新 tokenizer 编码、再解码，核对文本和 token 计数。随后检查训练与验证是否按文档隔离。",
    "选一个早期和一个后期预训练检查点，用固定提示生成。若后期损失更低却仍生成“用户、大白、小白”接龙，就把它记为对话格式缺陷，而非忽略。",
    "把基座与 SFT 版本放到同一组 100 条封存题上，对自然聊天、主动澄清和四轮记忆分别计数。某一类下降时先查看对应样本表达是否过于模板化。",
    "在报告中选一条结论，例如“验证损失下降”，贴出配置、日志行、对应 step 和评估命令。另把“会稳定聊天”列为待验证，避免从一个指标推出过多。",
    "第一次实验可选“短篇中文续写”而非通用助手：先定 20 条封存提示和可接受输出标准，再估算数据、显存与训练时长。完成小目标后再扩大。",
    "拿“今天 20°C，Python 3.12”做混合文本样本，查看特殊符号、数字与英文的 token 切分。训练前存下编码结果，换词表后重新比较长度与回编码。",
    "先跑 10 步并存检查点，主动停止进程，再恢复到第 11 步。核对 step、损失记录和采样位置；通过后才安排更长的训练。",
    "固定十条自然聊天和十条知识题，用相同模板测试基座与 SFT 版本。分别报告通过数和失败文本；若知识题退化，下一轮要考虑能力保留数据。",
    "在本机启动推理 API，发送正常、超长和未授权请求。记录模型版本、端口、状态码和耗时；再让客户端经网关访问，核对返回格式一致。",
    "最终报告展示一条成功生成和一条失败生成，连同固定输入、模型版本及命令。把‘跑通流程’与‘模型已具备稳定通用能力’分开陈述。",
]

assert len(EXAMPLE_DETAILS) == len(LESSONS) == 48
LESSONS = [
    (title, concept, f"{example}{EXAMPLE_DETAILS[number]}", question, answer)
    for number, (title, concept, example, question, answer) in enumerate(LESSONS)
]
